use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn generate_signature_mappings (compressor : & SignatureCompressor , output_file : & str) -> Result < () > { let mut output = String :: new () ; output . push_str ("# Macro Binding Signature Mappings\n") ; output . push_str ("# Generated by signature-compress\n\n") ; output . push_str ("## Prime Number Assignments (2 = most common)\n") ; let mut prime_assignments : Vec < _ > = compressor . prime_assignments . iter () . collect () ; prime_assignments . sort_by_key (| & (_ , & prime) | prime) ; for (signature , & prime) in prime_assignments { let frequency = compressor . frequency_map . get (signature) . unwrap_or (& 0) ; let default_emoji = "❓" . to_string () ; let emoji = compressor . emoji_assignments . get (signature) . unwrap_or (& default_emoji) ; output . push_str (& format ! ("{}: {} {} (freq: {})\n" , prime , emoji , signature , frequency)) ; } output . push_str ("\n## Emoji Assignments\n") ; for (signature , emoji) in & compressor . emoji_assignments { let prime = compressor . prime_assignments . get (signature) . unwrap_or (& 0) ; let frequency = compressor . frequency_map . get (signature) . unwrap_or (& 0) ; output . push_str (& format ! ("{}: {} → {} (freq: {})\n" , emoji , signature , prime , frequency)) ; } fs :: write (output_file , output) ? ; Ok (()) }